// How IC (Inline Cache) changes affect tiering decisions

// IC changes can delay optimization to allow functions to stabilize
void TieringManager::NotifyICChanged(Tagged<FeedbackVector> vector) {
  CodeKind code_kind = vector->shared_function_info()->HasBaselineCode()
                           ? CodeKind::BASELINE
                           : CodeKind::INTERPRETED_FUNCTION;

  // Don't delay tier-up if we haven't tiered up to baseline yet
  if (code_kind == CodeKind::INTERPRETED_FUNCTION &&
      CanCompileWithBaseline(isolate_, vector->shared_function_info()) &&
      vector->shared_function_info()->cached_tiering_decision() ==
          CachedTieringDecision::kPending) {
    return;
  }

  OptimizationDecision decision = ShouldOptimize(vector, code_kind);
  if (decision.should_optimize()) {
    Tagged<SharedFunctionInfo> shared = vector->shared_function_info();
    int bytecode_length = shared->GetBytecodeArray(isolate_)->length();
    Tagged<FeedbackCell> cell = vector->parent_feedback_cell();

    // Calculate new interrupt budget after IC change
    int invocations = v8_flags.minimum_invocations_after_ic_update;
    int bytecodes = std::min(bytecode_length, (kMaxInt >> 1) / invocations);
    int new_budget = invocations * bytecodes;
    int current_budget = cell->interrupt_budget();

    if (v8_flags.profile_guided_optimization &&
        shared->cached_tiering_decision() <=
            CachedTieringDecision::kEarlySparkplug) {
      // Track how many invocations were consumed before IC stabilized
      if (vector->invocation_count_before_stable() <
          v8_flags.invocation_count_for_early_optimization) {
        int new_invocation_count_before_stable;
        if (vector->interrupt_budget_reset_by_ic_change()) {
          // Initial interrupt budget was minimum_invocations_after_ic_update * bytecodes
          int new_consumed_budget = new_budget - current_budget;
          new_invocation_count_before_stable =
              vector->invocation_count_before_stable(kRelaxedLoad) +
              std::ceil(static_cast<float>(new_consumed_budget) / bytecodes);
        } else {
          // Initial interrupt budget was invocation_count_for_{maglev|turbofan} * bytecodes
          int total_consumed_budget =
              (maglev::IsMaglevEnabled()
                   ? v8_flags.invocation_count_for_maglev
                   : v8_flags.invocation_count_for_turbofan) *
                  bytecodes -
              current_budget;
          new_invocation_count_before_stable =
              std::ceil(static_cast<float>(total_consumed_budget) / bytecodes);
        }

        if (new_invocation_count_before_stable >=
            v8_flags.invocation_count_for_early_optimization) {
          vector->set_invocation_count_before_stable(
              v8_flags.invocation_count_for_early_optimization, kRelaxedStore);
          shared->set_cached_tiering_decision(CachedTieringDecision::kNormal);
        } else {
          vector->set_invocation_count_before_stable(
              new_invocation_count_before_stable, kRelaxedStore);
        }
      } else {
        shared->set_cached_tiering_decision(CachedTieringDecision::kNormal);
      }
    }

    // Reset interrupt budget if IC changed
    if (!v8_flags.profile_guided_optimization ||
        ShouldResetInterruptBudgetByICChange(
            shared->cached_tiering_decision())) {
      if (new_budget > current_budget) {
        if (v8_flags.trace_opt_verbose) {
          PrintF("[delaying optimization of %s, IC changed]\n",
                 shared->DebugNameCStr().get());
        }
        vector->set_interrupt_budget_reset_by_ic_change(true);
        cell->set_interrupt_budget(new_budget);
      }
    }
  }
}

// IC state tracking in FeedbackVector
class FeedbackVector : public TorqueGeneratedFeedbackVector<FeedbackVector, HeapObject> {
 public:
  // Tracks whether interrupt budget was reset due to IC change
  inline bool interrupt_budget_reset_by_ic_change() const;
  inline void set_interrupt_budget_reset_by_ic_change(bool value);

  // Tracks invocation count before ICs stabilized
  inline int invocation_count_before_stable(RelaxedLoadTag) const;
  inline void set_invocation_count_before_stable(int value, RelaxedStoreTag);

  // When ICs are monomorphic/polymorphic/megamorphic affects tiering
  enum class InlineCacheState : uint8_t {
    NO_FEEDBACK,
    UNINITIALIZED,
    MONOMORPHIC,
    RECOMPUTE_HANDLER,
    POLYMORPHIC,
    MEGAMORPHIC,
    MEGADOM,
    GENERIC
  };
};

// Cached tiering decisions in SharedFunctionInfo
class SharedFunctionInfo : public TorqueGeneratedSharedFunctionInfo<SharedFunctionInfo, HeapObject> {
 public:
  enum class CachedTieringDecision : uint8_t {
    kPending,           // No decision yet
    kEarlySparkplug,    // Should tier up to Sparkplug early
    kDelayMaglev,       // Delay Maglev optimization
    kEarlyMaglev,       // Should tier up to Maglev early
    kEarlyTurbofan,     // Should tier up to Turbofan early
    kNormal             // Normal tiering behavior
  };

  inline CachedTieringDecision cached_tiering_decision();
  inline void set_cached_tiering_decision(CachedTieringDecision decision);

  // Profile-guided optimization uses IC stability to make tiering decisions
  // - kEarlyMaglev/kEarlyTurbofan: optimize early if ICs stabilize quickly
  // - kDelayMaglev: delay optimization if ICs are changing frequently
  // - kNormal: standard tiering thresholds apply
};
